contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run tries to call withdraw and Command and checks they revert unless this contract is Owner
    function run(address target, bytes calldata data, uint256 sendAmount) public payable {
        require(address(this).balance >= sendAmount);

        // read current Owner and c balance before actions
        address ownerBefore = c.Owner();
        uint256 cBalBefore = address(c).balance;

        bool withdrawReverted;
        // attempt withdraw with some value (withdraw is payable in P)
        try c.withdraw{value: sendAmount}() {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        bool commandReverted;
        // attempt Command forwarding some value
        try c.Command{value: sendAmount}(target, data) {
            commandReverted = false;
        } catch {
            commandReverted = true;
        }

        // After attempts, read owner and c balance again
        address ownerAfter = c.Owner();
        uint256 cBalAfter = address(c).balance;

        // General rule:
        // If this contract is not the Owner, both withdraw and Command must have reverted,
        // and Owner and c balance must remain unchanged; if this contract is the Owner,
        // then at least one of withdraw or Command may succeed and balance may decrease but Owner stays the same.
        assert(
            (address(this) != ownerBefore && withdrawReverted && commandReverted && ownerAfter == ownerBefore && cBalAfter == cBalBefore)
            || (address(this) == ownerBefore && ownerAfter == ownerBefore)
        );
    }

    // allow receiving Ether for sendAmount funding
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run takes an address to receive funds from multiplicate and an amount to send with the call
    function run(address payable adr, uint amount) public payable {
        require(address(this).balance >= amount, "insufficient test balance");
        // Capture c balance before
        uint before = address(c).balance;

        // Call multiplicate with provided amount of Ether
        bool reverted;
        try c.multiplicate{value: amount}(adr) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint after = address(c).balance;
        uint myBal = address(this).balance;

        // General rule:
        // If the call did not revert and amount >= before, then the contract must have sent (before + amount)
        // out to adr, leaving c balance 0. If amount < before or the call reverted, c.balance must be unchanged.
        // We express observable consequences: when successful transfer happens, c.balance == 0 and it only happens when amount >= before and not reverted.
        assert(
            // successful send implies condition amount >= before and c balance zero
            (!reverted && amount >= before && after == 0)
            // if it reverted or amount < before, then c balance must be unchanged
            || (reverted || amount < before) && (after == before)
        );
    }

    receive() external payable {}
}

