contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // adr: recipient for multiplicate; amount: value to send with the call
    function run(address adr, uint amount) public payable {
        require(address(this).balance >= amount);
        // Observe owner and balance before
        address ownerBefore = c.Owner();
        uint beforeBal = address(c).balance;

        bool reverted;
        try c.multiplicate{value: amount}(adr) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe owner and balance after
        address ownerAfter = c.Owner();
        uint afterBal = address(c).balance;

        // General rule:
        // - The Owner public variable never changes due to multiplicate (ownerBefore == ownerAfter).
        // - If the call reverted then balance is unchanged.
        // - If the call succeeded then the contract balance cannot have increased (afterBal <= beforeBal + amount)
        //   and if it actually sent funds (afterBal < beforeBal + amount) that still implies Owner stayed the same.
        assert(
            ownerBefore == ownerAfter
            && (reverted ? afterBal == beforeBal : afterBal <= beforeBal + amount)
        );
    }

    receive() external payable {}
}

