contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take parameters to try various callers and values/data for Command.
    // amount is the Ether we forward to c.Command; data is arbitrary calldata; adr is target address for Command.
    function run(address adr, bytes calldata data, uint256 amount) public payable {
        require(address(this).balance >= amount);

        // Read owner and c balance before the call
        address ownerBefore = c.Owner();
        uint256 balBefore = address(c).balance;

        bool reverted;
        // Call Command as this contract, forwarding 'amount' wei
        try c.Command{value: amount}(adr, data) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 balAfter = address(c).balance;

        // General rule asserted:
        // - If the call reverted then it must be because msg.sender != Owner (withdraw/Command gated by owner).
        //   Since only require in Command checks owner, a revert implies this contract is not the owner.
        // - If the call did not revert then c.balance changes by at most +amount (it cannot magically gain more than the forwarded value).
        //   We express this as: balAfter <= balBefore + amount.
        // These combined form a general invariant about Command behavior for all inputs.
        assert(
            (reverted && (address(this) != ownerBefore))
            || (!reverted && (balAfter <= balBefore + amount))
        );
    }

    // Allow the test contract to receive Ether so it can forward 'amount'
    receive() external payable {}
}
